// === Tab: mySketch ===
// Title: Motion Catalog
// Author: FAL
// Date: 3. Oct. 2017
// Made with p5.js v0.5.14 (plugin: p5.sound.js v0.3.5)

// (It's my first time coding with p5.js!!)


var soundEnabled = true;
var myOscillator;
var playingSound;
var previousSoundTimeStamp;

var myElementSet;

var frameCountPerCicle = 60;
var currentCicleFrameCount;
var
  currentCicleProgressRatio,
  currentCicleQuadEaseInRatio,
  currentCicleQuadEaseOutRatio,
  currentCicleQuartEaseInRatio,
  currentCicleQuartEaseOutRatio;

var backgroundColor;

function setup() {
  createCanvas(640, 640);
  backgroundColor = color(240);

  myOscillator = new p5.Oscillator();
  myOscillator.setType('sine');
  myOscillator.freq(880);
  myOscillator.amp(0);
  myOscillator.start();

  ellipseMode(CENTER);
  rectMode(CENTER);

  myElementSet = new ElementSet(4, 40);

  myElementSet.push(drawShrinkingCircle);
  myElementSet.push(drawExpandingRipple);
  myElementSet.push(drawPulsingQuadrangle);
  myElementSet.push(drawTransformingEllipse);

  myElementSet.push(drawFadingAwayCircle);
  myElementSet.push(drawHittingLine);
  myElementSet.push(drawBouncingCircle);
  myElementSet.push(drawJitteringCircle);

  myElementSet.push(drawRotatingCross);
  myElementSet.push(drawRotatingCircles);
  myElementSet.push(drawOrbit);
  myElementSet.push(drawPulsingSomething);

  myElementSet.push(drawPoppingCircles);
  myElementSet.push(drawExplodingSquare);
  myElementSet.push(drawSpectrum);
  myElementSet.push(drawString);
}

function draw() {
  background(backgroundColor);
  updateCurrentCicleProgress();

  myElementSet.display();

  if (soundEnabled) {
    if (frameCount % frameCountPerCicle == 0) playSound();
    if (playingSound && millis() - previousSoundTimeStamp > 20) {
      myOscillator.amp(0, 0.1);
      playingSound = false;
    }
  }
}

function updateCurrentCicleProgress() {
  currentCicleFrameCount = frameCount % frameCountPerCicle;
  currentCicleProgressRatio = currentCicleFrameCount / frameCountPerCicle;
  currentCicleQuadEaseInRatio = currentCicleProgressRatio * currentCicleProgressRatio;
  currentCicleQuadEaseOutRatio = -sq(currentCicleProgressRatio - 1) + 1;
  currentCicleQuartEaseInRatio = pow(currentCicleProgressRatio, 4);
  currentCicleQuartEaseOutRatio = -pow(currentCicleProgressRatio - 1, 4) + 1;
}

function mouseClicked() {
  if (soundEnabled) myOscillator.stop();
  else myOscillator.start();
  soundEnabled = !soundEnabled;
}

function playSound() {
  myOscillator.amp(1, 0.02);
  // myOscillator.amp(0, 0.1, 0.02);  // Did not work in OpenProcessing, therefore used millis() as an alternative
  previousSoundTimeStamp = millis();
  playingSound = true;
}



var ElementSet = function(elementXCount, elementDisplaySize) {
  var elementArray = [];
  var positionInterval = width / (elementXCount + 1);
  var xIndex = 0;
  var yIndex = 0;

  this.push = function(displayFunction) {
    elementArray.push(new Element(
      (xIndex + 1) * positionInterval,
      (yIndex + 1) * positionInterval,
      displayFunction
    ));
    xIndex++;
    if (xIndex >= elementXCount) {
      xIndex = 0;
      yIndex++;
    }
  };

  this.display = function() {
    for (var elementIndex = 0, elementNumber = elementArray.length; elementIndex < elementNumber; elementIndex++) {
      elementArray[elementIndex].display(elementDisplaySize);
    }
  };
};

var Element = function(x, y, displayFunction) {
  this.xPosition = x;
  this.yPosition = y;
  this.display = displayFunction;
};



function drawShrinkingCircle(size) {
  var diameter = size * (1.5 - currentCicleQuartEaseOutRatio);
  noStroke();
  fill(0);
  ellipse(this.xPosition, this.yPosition, diameter, diameter);
}

function drawExpandingRipple(size) {
  var diameter = size * 1.5 * currentCicleQuartEaseOutRatio;
  stroke(0);
  strokeWeight(Math.max(0.1, Math.abs(size * 0.2 * (1 - currentCicleQuartEaseOutRatio))));
  noFill();
  ellipse(this.xPosition, this.yPosition, diameter, diameter);
}

function drawHittingLine(size) {
  var offsetYPosition = -size * 0.25 + size * 0.5 * (1 - currentCicleQuartEaseOutRatio);
  noStroke();
  fill(0);
  rect(this.xPosition, this.yPosition + offsetYPosition, size * 0.1, size);
}

function drawPulsingQuadrangle(size) {
  var radius = size * 0.5;
  if (currentCicleProgressRatio < 0.1) {
    radius += radius * currentCicleProgressRatio * 10;
  } else if (currentCicleProgressRatio < 0.2) {
    radius += radius * (1 - (currentCicleProgressRatio - 0.1) * 10);
  }
  stroke(0);
  strokeWeight(1);
  noFill();
  quad(
    this.xPosition + radius, this.yPosition,
    this.xPosition, this.yPosition + radius,
    this.xPosition - radius, this.yPosition,
    this.xPosition, this.yPosition - radius
  );
}

function drawRotatingCross(size) {
  var rotationAngle = PI * currentCicleQuartEaseOutRatio;
  noStroke();
  fill(0);
  push();
  translate(this.xPosition, this.yPosition);
  rotate(rotationAngle);
  rect(0, 0, size, size * 0.15);
  rect(0, 0, size * 0.15, size);
  pop();
}

function drawRotatingCircles(size) {
  var rotationAngle = PI * currentCicleQuartEaseOutRatio;
  var diameter = size * 0.2;
  noStroke();
  fill(0);
  push();
  translate(this.xPosition, this.yPosition);
  rotate(rotationAngle);
  ellipse(0, -size * 0.5, diameter, diameter);
  ellipse(0, +size * 0.5, diameter, diameter);
  pop();
}

function drawFadingAwayCircle(size) {
  var alpha = 255 * (1 - currentCicleQuartEaseOutRatio);
  var offsetYPosition = size * 1.2 * (0.5 - currentCicleQuartEaseOutRatio);
  var diameter = size * 0.5;
  noStroke();
  fill(0, alpha);
  ellipse(this.xPosition, this.yPosition + offsetYPosition, diameter, diameter);
}

function drawBouncingCircle(size) {
  var offsetYPosition = size * 0.5 - size * 5 * currentCicleProgressRatio + size * 5 * currentCicleQuadEaseInRatio;
  var diameter = size * 0.3;
  noStroke();
  fill(0);
  ellipse(this.xPosition, this.yPosition + offsetYPosition, diameter, diameter);
}

function drawTransformingEllipse(size) {
  var xAxis = size * 0.6 * (2 - currentCicleQuartEaseOutRatio);
  var yAxis = size * 0.6 * (1 + currentCicleQuartEaseOutRatio);
  stroke(0);
  strokeWeight(1);
  noFill();
  ellipse(this.xPosition, this.yPosition, xAxis, yAxis);
}

function drawOrbit(size) {
  var angle = -HALF_PI + TWO_PI * currentCicleQuartEaseOutRatio;
  var particleSize = size * 0.2;
  var radius = size * 0.5;
  stroke(0);
  strokeWeight(1);
  noFill();
  ellipse(this.xPosition, this.yPosition, size, size);
  noStroke();
  fill(0);
  ellipse(this.xPosition + radius * cos(angle), this.yPosition + radius * sin(angle), particleSize, particleSize);
}

function drawPoppingCircles(size) {
  var diameter = size * 0.3 * (1 - currentCicleProgressRatio);
  var distance = size * 0.7 * (currentCicleQuartEaseOutRatio);
  stroke(0);
  strokeWeight(1);
  noFill();
  for (var i = 0; i < 5; i++) {
    var rotationAngle = -HALF_PI + i * TWO_PI / 5;
    push();
    translate(this.xPosition, this.yPosition);
    rotate(rotationAngle);
    ellipse(distance, 0, diameter, diameter);
    pop();
  }
}

function drawExplodingSquare(size) {
  var sideLength = size * 0.7;
  var alpha = 255 * currentCicleQuadEaseInRatio;
  var rotationAngle = TWO_PI * currentCicleQuartEaseOutRatio;
  var particleSize = size * 0.2;
  var particleBaseDistance = size * currentCicleQuadEaseOutRatio;
  var particleRotationAngle = TWO_PI * currentCicleProgressRatio;
  var particleAlpha = 255 * (1 - currentCicleQuartEaseOutRatio);

  stroke(0, alpha);
  strokeWeight(1);
  noFill();
  push();
  translate(this.xPosition, this.yPosition);
  rotate(rotationAngle);
  rect(0, 0, sideLength, sideLength);
  pop();

  stroke(0, particleAlpha);
  for (var i = 0; i < 16; i++) {
    var directionAngle = i * TWO_PI / 16;
    var distanceFactor = 1 + 0.5 * sin(i * 10);
    push();
    translate(
      this.xPosition + particleBaseDistance * distanceFactor * cos(directionAngle),
      this.yPosition + particleBaseDistance * distanceFactor * sin(directionAngle)
    );
    rotate(particleRotationAngle);
    rect(0, 0, particleSize, particleSize);
    pop();
  }
}

function drawPulsingSomething(size) {
  var angle = TWO_PI * currentCicleQuartEaseOutRatio;
  var particleSize = size * 0.2;
  var halfSize = size * 0.5;
  stroke(0);
  strokeWeight(1);
  line(this.xPosition - halfSize, this.yPosition, this.xPosition + halfSize, this.yPosition);
  noStroke();
  fill(0);
  ellipse(
    this.xPosition - halfSize + size * currentCicleProgressRatio,
    this.yPosition - halfSize * sin(angle),
    particleSize,
    particleSize
  );
}

function drawJitteringCircle(size) {
  var maxDisplacement = size * 0.5 * (1 - currentCicleQuadEaseOutRatio);
  var diameter = size * 0.3;
  noStroke();
  fill(0);
  ellipse(
    this.xPosition + random(-maxDisplacement, maxDisplacement),
    this.yPosition + random(-maxDisplacement, maxDisplacement),
    diameter,
    diameter
  );
}

function drawSpectrum(size) {
  var amplitude = size * (0.2 + 0.8 * (1 - currentCicleQuadEaseOutRatio));
  var barWidth = size * 0.1;
  var barInterval = size * 0.2;
  var halfSize = size * 0.5;
  var offsetXPosition = -halfSize + barWidth * 0.5;
  push();
  rectMode(CORNER);
  noStroke();
  fill(0);
  for (var i = 0; i < 6; i++) {
    var barLength = amplitude * random(1);
    rect(
      this.xPosition + offsetXPosition + i * barInterval,
      this.yPosition + halfSize - barLength,
      barWidth,
      barLength
    );
  }
  pop();
}

function drawString(size) {
  var diameter = size * 0.15;
  var amplitude = size * 0.5 * (1 - currentCicleProgressRatio);
  var halfLength = size * 0.7;
  var yDisplacement = amplitude;
  if (currentCicleFrameCount % 2 == 0) {
    yDisplacement = -yDisplacement;
  }

  stroke(0);
  strokeWeight(1);
  noFill();
  for (var i = 0; i < 3; i++) {
    if (i >= 1) {
      yDisplacement = amplitude * random(-1, 1);
    }
    bezier(
      this.xPosition - halfLength, this.yPosition,
      this.xPosition, this.yPosition + yDisplacement,
      this.xPosition, this.yPosition + yDisplacement,
      this.xPosition + halfLength, this.yPosition
    );
  }
  noStroke();
  fill(0);
  ellipse(this.xPosition - halfLength, this.yPosition, diameter, diameter);
  ellipse(this.xPosition + halfLength, this.yPosition, diameter, diameter);
}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        static dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

// 1.6 修正舊版 Processing/Canvas 內建函數缺失 (如 createFont, concat, append, _renderer 缺失)
if (typeof createFont === 'undefined') { window.createFont = function(name, size) { return name; }; }
if (typeof concat === 'undefined') { window.concat = function(a, b) { return (a || []).concat(b || []); }; }
if (typeof append === 'undefined') { window.append = function(array, value) { if(array) { array.push(value); } return array; }; }
if (typeof _renderer === 'undefined') { window._renderer = { _setAttributes: function() {} }; }

// 1.7 免疫機器學習與人臉偵測 (ml5.js, clmtrackr, aiptag, lime) 缺失與內部指標 null 導致的崩潰 (修復 ml5.js .features of null 報錯)
if (typeof window.clm === 'undefined') {
    window.clm = {
        tracker: class {
            init() {}
            start() {}
            track() { return []; }
            getCurrentPosition() { return []; }
            getScore() { return 0; }
        }
    };
}
if (typeof window.ml5 === 'undefined') {
    const ml5MockObj = {
        detectStart: function() {},
        features: { get: function() { return []; } },
        on: function() {},
        ready: Promise.resolve(),
        loadModel: Promise.resolve()
    };
    window.ml5 = {
        bodypix: function() { return ml5MockObj; },
        faceapi: function() { return ml5MockObj; },
        handpose: function() { return ml5MockObj; },
        poseNet: function() { return ml5MockObj; },
        objectDetector: function() { return ml5MockObj; }
    };
}
if (typeof window.aiptag === 'undefined') { window.aiptag = {}; }
if (typeof window.lime === 'undefined') { window.lime = {}; }

// 1.8 免疫 3D 物理引擎與高階渲染 (THREE.Group, Tone.js, p5.asciify, REGL, Voronoi, PolyK, qrcode, P5Capture) 缺失導致的崩潰
if (typeof window.THREE === 'undefined') {
    window.THREE = {
        Group: class {},
        Scene: class {},
        PerspectiveCamera: class {},
        WebGLRenderer: class { setSize() {} },
        Mesh: class {},
        BoxGeometry: class {}
    };
}
if (typeof window.Tone === 'undefined') {
    window.Tone = {
        Player: class { play() {} start() {} stop() {} connect() {} toDestination() {} },
        Players: class { play() {} start() {} stop() {} connect() {} toDestination() {} },
        Sampler: class { triggerAttackRelease() {} connect() {} toDestination() {} },
        Sequence: class { start() {} stop() {} },
        Transport: { start: function() {}, stop: function() {}, bpm: { value: 120 } }
    };
}
if (typeof window.createREGL === 'undefined') {
    window.createREGL = function() {
        const regl = function() {};
        regl.texture = function() { return { resize: function() {} }; };
        regl.buffer = function() { return { subdata: function() {} }; };
        regl.framebuffer = function() { return { use: function(cb) { cb(); } }; };
        return regl;
    };
}
if (typeof window.Voronoi === 'undefined') {
    window.Voronoi = class {
        compute() { return { cells: [], edges: [] }; }
    };
}
if (typeof window.qrcode === 'undefined') {
    window.qrcode = function(data) {
        return {
            createImgTag: function() { return ""; },
            createTableTag: function() { return ""; },
            createSvgTag: function() { return ""; }
        };
    };
    window.qrcode.stringToBytes = function(s) { return []; };
}
if (typeof window.PolyK === 'undefined') {
    window.PolyK = {
        Slice: function() { return []; },
        Triangulate: function() { return []; },
        getArea: function() { return 0; }
    };
}
if (typeof window.P5Capture === 'undefined') {
    window.P5Capture = {
        getInstance: function() {
            return { start: function() {}, stop: function() {}, setFormat: function() {} };
        },
        setDefaultOptions: function() {}
    };
}

// 1.9 免疫 OPC (OpenProcessing Controller) 與 WebGL 內部 setUniform 崩潰
if (typeof window.OPC === 'undefined') {
    window.OPC = {
        title: function() {},
        slider: function() {},
        button: function() {},
        toggle: function() {},
        color: function() {}
    };
}
if (typeof p5 !== 'undefined' && p5.Shader) {
    const origSetUniform = p5.Shader.prototype.setUniform;
    p5.Shader.prototype.setUniform = function(name, val) {
        if (!this) return this;
        try {
            return origSetUniform.call(this, name, val);
        } catch(e) {
            return this;
        }
    };
}

// 1.95 免疫某些特定遊戲模組對 parent / maeExportApis_ 或是唯讀屬性的寫入崩潰
try {
  if (typeof window.parent !== 'undefined') {
    if (!window.parent.maeExportApis_) {
      try {
        window.parent.maeExportApis_ = function() {};
      } catch(e) {}
    }
  }
} catch(e) {}

// 1.96 免疫 textmode 缺失以及 loadSVG / p5.SVG 插件型別拋錯
if (typeof textmode === 'undefined') { window.textmode = function() {}; }
if (typeof MAT === 'undefined') { window.MAT = []; }
if (typeof SIDES === 'undefined') { window.SIDES = 4; }
if (typeof GRIDBOX === 'undefined') { window.GRIDBOX = 10; }
if (typeof COLUMNS === 'undefined') { window.COLUMNS = 5; }
if (typeof tileSize === 'undefined') { window.tileSize = 30; }
if (typeof mouseTileX === 'undefined') { window.mouseTileX = 0; }
if (typeof p5 !== 'undefined') {
  if (!p5.prototype.loadSVG) {
    p5.prototype.loadSVG = function(path, success, failure) {
      if (success) success({});
      return {};
    };
  }
  // 免疫 window.VERSION 唯讀寫入錯誤
  try {
    Object.defineProperty(window, 'VERSION', {
      value: "p5-stub",
      writable: true,
      configurable: true
    });
  } catch(e) {}
}

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || path.startsWith('http') || (path.startsWith('data:') === false && path.indexOf('.') === -1)) {
            // 當發現是遠端 URL、相對路徑或格式無副檔名時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖與 CORS 錯誤
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };

    // 修正 img.loadPixels / img.resize 缺失與未非同步載入完成呼叫
    if (!p5.Image.prototype.loadPixels) { p5.Image.prototype.loadPixels = function() { return this; }; }
    if (!p5.Image.prototype.resize) { p5.Image.prototype.resize = function() { return this; }; }
    if (!p5.Image.prototype.get) { p5.Image.prototype.get = function() { return [0,0,0,255]; }; }
    if (!p5.Image.prototype.width) {
        Object.defineProperty(p5.Image.prototype, 'width', {
            get: function() { return this._width || 1280; },
            set: function(v) { this._width = v; }
        });
    }
    if (!p5.Image.prototype.height) {
        Object.defineProperty(p5.Image.prototype, 'height', {
            get: function() { return this._height || 720; },
            set: function(v) { this._height = v; }
        });
    }

    // 修正 p5.Graphics / p5.Renderer / Element.prototype.style
    if (p5.Graphics && p5.Graphics.prototype) {
        if (!p5.Graphics.prototype.loadPixels) { p5.Graphics.prototype.loadPixels = function() { return this; }; }
    }
}

// 2.2 修正 p5.Table / loadTable / getRowCount 缺失與錯誤
if (typeof p5 !== 'undefined' && p5.Table) {
    if (!p5.Table.prototype.getRowCount) { p5.Table.prototype.getRowCount = function() { return 0; }; }
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (!this || this.width === 0 || this.height === 0) {
            return [0,0,0,255];
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return [0,0,0,255];
        }
    };
}

